function englishWorkspace(saved) {
 const copy=v=>legacyCopy[v]??v;
 const activityCopy=v=>Object.entries({...legacyActivityCopy,...legacyCopy}).sort((a,b)=>b[0].length-a[0].length).reduce((text,[from,to])=>text.replaceAll(from,to),String(v));
 return {...saved,profile:{...saved.profile,country:copy(saved.profile.country)},
  campaigns:saved.campaigns.map(c=>['curr-welcome','curr-loyalty','north-welcome','harbor-welcome'].includes(c.legacyId||c.id)?{...c,name:copy(c.name),description:copy(c.description)}:c),
  holders:saved.holders.map(h=>({...h,source:copy(h.source)})),
  activity:saved.activity.map(a=>({...a,title:activityCopy(a.title),detail:activityCopy(a.detail)}))};
}
